import os, json
ROOT=r'D:/repository'
SKIP={'node_modules','.git','dist','build','__pycache__','.idea','.vscode','coverage','target'}
EXTS={'.vue','.js','.ts','.scss','.css','.html','.json','.md','.conf','.ini','.properties'}
