# print full content of 25,30
for i in [25,30]:
    print('#### CONTENT[%d] %s'%(i,cands[i]['uri']))
    print(cands[i]['content'])
    print()

def scan(proj, syms):
    base=os.path.join(ROOT,proj)
    res={s:[] for s in syms}
    if not os.path.isdir(base): return {'DIR_EXISTS':False,'res':res}
    for dp,dns,fns in os.walk(base):
        dns[:]=[x for x in dns if x not in SKIP]
        for fn in fns:
            if os.path.splitext(fn)[1].lower() not in EXTS: continue
            fp=os.path.join(dp,fn)
            try:
                if os.path.getsize(fp)>800000: continue
                txt=open(fp,encoding='utf-8',errors='ignore').read()
            except Exception: continue
            for s in syms:
                if s in txt and len(res[s])<5:
                    res[s].append(os.path.relpath(fp,ROOT).replace('\\','/'))
    return {'DIR_EXISTS':True,'res':res}

